```java src/pag/domains/gen/DifferenceDomain.java
package pag.domains.gen;

import java.math.BigInteger;
import java.util.*;
import pag.api.*;

/**
 * A backward abstract domain for integer program reachability.
 *
 * <p>The state is a disjunction of convex "difference constraint" systems.
 * Each convex system stores implied bounds of the form
 * {@code target - source <= bound}, where a special zero node represents the
 * constant 0. This gives absolute bounds ({@code x <= c}, {@code x >= c}) and
 * relative bounds ({@code x - y <= c}).
 *
 * <p>The domain is sound over-approximating. Operations that cannot be
 * represented exactly (for example non-linear expressions) are ignored in a
 * sound, precision-losing way.
 */
public class DifferenceDomain implements Domain<DifferenceDomain.State> {

    private static final String ZERO = "�ZERO";
    private static final BigInteger ONE = BigInteger.ONE;
    private static final BigInteger NEG_ONE = BigInteger.ONE.negate();
    private static final BigInteger TWO = BigInteger.valueOf(2);
    private static final BigInteger TEN = BigInteger.valueOf(10);

    /** Cap on disjuncts; exceeding it safely widens to top. */
    private static final int MAX_DISJUNCTS = 32;

    private record Pair(String target, String source) {}

    private static final class Convex {
        private final Map<Pair, BigInteger> bounds;

        Convex(Map<Pair, BigInteger> bounds) {
            this.bounds = bounds;
        }

        boolean isTop() {
            return bounds.isEmpty();
        }
    }

    public static final class State {
        private final boolean bottom;
        private final List<Convex> disjuncts;

        private State(boolean bottom, List<Convex> disjuncts) {
            this.bottom = bottom;
            this.disjuncts = disjuncts;
        }

        boolean isTop() {
            return !bottom && disjuncts.size() == 1 && disjuncts.get(0).isTop();
        }
    }

    private static final State TOP = new State(false, List.of(new Convex(Map.of())));
    private static final State BOTTOM = new State(true, List.of());

    private enum IneqResult { OK, BOTTOM, IGNORE }

    public DifferenceDomain() {
    }

    @Override
    public String name() {
        return "difference";
    }

    @Override
    public State top() {
        return TOP;
    }

    @Override
    public State bottom() {
        return BOTTOM;
    }

    @Override
    public boolean isBottom(State s) {
        return s.bottom;
    }

    @Override
    public boolean entails(State a, State b) {
        if (a.bottom) return true;
        if (b.bottom) return false;
        if (b.isTop()) return true;

