private State close(Map<Pair, BigInteger> explicit) {
  if (explicit.isEmpty()) return TOP;
  // If any explicit Pair target==source with bound<0 -> bottom.
  // Collect vars.
  Set<String> varSet = new HashSet<>();
  for (Pair p : explicit.keySet()) { varSet.add(p.target()); varSet.add(p.source()); }
  // Always include ZERO? Not necessary unless appears. But for one-variable bounds, Pair(v, ZERO) includes ZERO. Good.
  List<String> vars = new ArrayList<>(varSet);
  // Could sort for determinism.
  Collections.sort(vars);
  Map<String,Integer> idx = new HashMap<>();
  int n=vars.size();
  BigInteger[][] dist = new BigInteger[n][n];
  for i dist[i][i]=BigInteger.ZERO;
  for (Map.Entry<Pair,BigInteger> e : explicit.entrySet()) {
    Pair p=e.getKey(); BigInteger c=e.getValue();
    if (p.target().equals(p.source())) { if (c.signum()<0) return BOTTOM; else continue; }
    int from=idx.get(p.source()); int to=idx.get(p.target());
    if (dist[from][to]==null || c.compareTo(dist[from][to])<0) dist[from][to]=c;
  }
  // Floyd
  for k...
    for i...
      if dist[i][k]==null continue;
      for j...
        if dist[k][j]==null continue;
        BigInteger sum = dist[i][k].add(dist[k][j]);
        if dist[i][j]==null || sum.compareTo(dist[i][j])<0) {
           dist[i][j]=sum;
           if (i==j && sum.signum()<0) return BOTTOM;
        }
  // After loop, check diagonals negative (could have been set initially).
  for i if dist[i][i]!=null && dist[i][i].signum()<0 return BOTTOM;
  Map<Pair,BigInteger> closed = new HashMap<>();
  for i 0..n-1 for j 0..n-1 if i!=j && dist[i][j]!=null {
     Pair p = new Pair(vars.get(j), vars.get(i)); // target=to j, source=from i
     closed.put(p, dist[i][j]);
  }
  if (closed.isEmpty()) return TOP;
  return new State(false, Map.copyOf(closed)); // Map.copyOf immutable, but need stable.
}
