private State normalize(List<Convex> in) {
    if (in == null || in.isEmpty()) return BOTTOM;
    List<Convex> list = new ArrayList<>();
    for (Convex c : in) {
        if (c == null) continue;
        if (c.isTop()) return TOP;
        boolean dup = false;
        for (Convex o : list) {
            if (o.bounds.equals(c.bounds)) { dup = true; break; }
        }
        if (!dup) list.add(c);
    }
    if (list.isEmpty()) return BOTTOM;
    boolean changed = true;
    while (changed) {
        changed = false;
        outer:
        for (int i = 0; i < list.size(); i++) {
            for (int j = 0; j < list.size(); j++) {
                if (i == j) continue;
                if (convexEntails(list.get(i), list.get(j))) {
                    list.remove(i);
                    changed = true;
                    break outer;
                }
            }
        }
    }
    if (list.isEmpty()) return BOTTOM;
    if (list.size() > MAX_DISJUNCTS) return TOP;
    return new State(false, List.copyOf(list));
