private Form evalLinear(RVal rv) {
    return switch (rv) {
        case RVal.IntConst c -> Form.constant(c.v());
        case LVal.Local l -> Form.var(l.name());
        case LVal.StaticField s -> {
            BigInteger v = knownStatic(s);
            yield v == null ? Form.var(staticName(s)) : Form.constant(v);
        }
        case RVal.Binop b -> evalBinop(b);
    };
}
private Form evalBinop(RVal.Binop b) {
    BinOp op = b.op();
    switch (op) {
        case Add: {
            Form l = evalLinear(b.l()); Form r = evalLinear(b.r());
            if (l == null || r == null) return null;
            return l.add(r);
        }
        case Sub: { ... }
        case Mult: {
            Form l = evalLinear(b.l()); Form r = evalLinear(b.r());
            if (l == null && r == null) return null;
            if (l == null) {
                if (r != null && r.isConstant() && r.constValue().signum() == 0) return Form.zero();
                return null;
            }
            if (r == null) {
                if (l.isConstant() && l.constValue().signum() == 0) return Form.zero();
                return null;
            }
            if (l.isConstant() && r.isConstant()) return Form.constant(l.constValue().multiply(r.constValue()));
            if (l.isConstant()) return r.multiply(l.constValue());
            if (r.isConstant()) return l.multiply(r.constValue());
            return null;
        }
        default:
            return null;
    }
}
