private IneqResult addInequality(Map<Pair, BigInteger> explicit, Form form, BigInteger rhs) {
    if (form == null) return IneqResult.IGNORE;
    Map<String, BigInteger> coeffs = form.coeffMap();
    BigInteger c0 = form.constValue();
    BigInteger rhsAdj = rhs.subtract(c0);
    if (coeffs.isEmpty()) {
        return c0.compareTo(rhs) <= 0 ? IneqResult.OK : IneqResult.BOTTOM;
    }
    if (coeffs.size() == 1) {
        Map.Entry<String, BigInteger> e = coeffs.entrySet().iterator().next();
        String v = e.getKey();
        BigInteger c = e.getValue();
        if (c.signum() == 0) return IneqResult.OK;
        if (c.equals(ONE)) return addPair(explicit, v, ZERO, rhsAdj);
        if (c.equals(NEG_ONE)) return addPair(explicit, ZERO, v, rhsAdj);
        if (c.signum() > 0) {
            return addPair(explicit, v, ZERO, rhsAdj.floorDiv(c));
        } else {
            BigInteger bound = rhsAdj.ceilDiv(c);
            return addPair(explicit, ZERO, v, bound.negate());
        }
    }
    if (coeffs.size() == 2) {
        Iterator<Map.Entry<String, BigInteger>> it = coeffs.entrySet().iterator();
        Map.Entry<String, BigInteger> e1 = it.next();
        Map.Entry<String, BigInteger> e2 = it.next();
        if (e1.getValue().equals(e2.getValue().negate())) {
            BigInteger c = e1.getValue();
            if (c.signum() > 0) {
                return addPair(explicit, e1.getKey(), e2.getKey(), rhsAdj.floorDiv(c));
            } else {
                BigInteger bound = rhsAdj.ceilDiv(c);
                return addPair(explicit, e2.getKey(), e1.getKey(), bound.negate());
            }
        }
        return IneqResult.IGNORE;
    }
    return IneqResult.IGNORE;
}
