private boolean entailsFormEqZeroConvex(Convex post, Form form) {
    if (form == null) return false;
    if (form.isConstant()) return form.constValue().signum() == 0;
    Map<Pair, BigInteger> explicit = new HashMap<>();
    IneqResult r1 = addInequality(explicit, form, BigInteger.ZERO);
    if (r1 != IneqResult.OK) return false;
    IneqResult r2 = addInequality(explicit, form.negate(), BigInteger.ZERO);
    if (r2 != IneqResult.OK) return false;
    Convex eq = closeConvex(explicit);
    if (eq == null) return false;
    return convexEntails(post, eq);
}
